mapper.select:
SELECT id, username, password, email, role, location_id, created_at, default_start_time, default_end_time
FROM users
WHERE id = #{id}

SELECT id, username, password, email, role, location_id, created_at, default_start_time, default_end_time
FROM users
WHERE username = #{username}

SELECT id, username, password, email, role, location_id, created_at, default_start_time, default_end_time
FROM users
WHERE email = #{email}

SELECT COUNT(*) > 0 THEN TRUE ELSE FALSE END
FROM users
WHERE username = #{username}
